  1→import { ChevronLeft, ChevronRight, FileSpreadsheet, Loader2 } from 'lucide-react';
  2→import { useState } from 'react';
  3→
  4→import { CriteriaTable } from '../components/criteria-table/CriteriaTable';
  5→import { columns } from '../components/criteria-table/columns';
  6→import { FilterBar } from '../components/criteria-table/filters';
  7→import { Button } from '../components/ui/Button';
  8→import { useCriteriaSpreadsheet } from '../hooks/useCriteriaSpreadsheet';
  9→
 10→export default function CriteriaSpreadsheet() {
 11→    const [page, setPage] = useState(1);
 12→    const [criteriaType, setCriteriaType] = useState('');
 13→    const [category, setCategory] = useState('');
 14→    const [minConfidence, setMinConfidence] = useState('');
 15→
 16→    const { data, isLoading, error } = useCriteriaSpreadsheet({
 17→        page,
 18→        pageSize: 50,
 19→        criteriaType: criteriaType || undefined,
 20→        category: category || undefined,
 21→        minConfidence: minConfidence ? Number.parseFloat(minConfidence) : undefined,
 22→        sortBy: 'confidence',
 23→        sortOrder: 'desc',
 24→    });
 25→
 26→    const totalCriteria = data?.total ?? 0;
 27→    const totalPages = data?.pages ?? 1;
 28→    const items = data?.items ?? [];
 29→
 30→    // Stats
 31→    const inclusionCount = items.filter((i) => i.criteria_type === 'inclusion').length;
 32→    const exclusionCount = items.filter((i) => i.criteria_type === 'exclusion').length;
 33→    const avgConfidence =
 34→        items.length > 0 ? items.reduce((s, i) => s + i.confidence, 0) / items.length : 0;
 35→    const groundedCount = items.filter((i) => i.entities.some((e) => e.grounding_code)).length;
 36→
 37→    return (
 38→        <div className="container mx-auto p-6 space-y-6">
 39→            {/* Header */}
 40→            <header className="flex items-center justify-between">
 41→                <div className="flex items-center gap-3">
 42→                    <FileSpreadsheet className="h-7 w-7 text-blue-600" />
 43→                    <div>
 44→                        <h1 className="text-2xl font-bold text-foreground">Structured Criteria</h1>
 45→                        <p className="text-sm text-muted-foreground">
 46→                            Browse and filter extracted eligibility criteria across all protocols
 47→                        </p>
 48→                    </div>
 49→                </div>
 50→                <div className="text-sm text-muted-foreground tabular-nums">
 51→                    {totalCriteria} criteria total
 52→                </div>
 53→            </header>
 54→
 55→            {/* Stats summary */}
 56→            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
 57→                <div className="rounded-lg border bg-card p-4">
 58→                    <div className="text-2xl font-bold text-emerald-600 tabular-nums">
 59→                        {inclusionCount}
 60→                    </div>
 61→                    <div className="text-xs text-muted-foreground">Inclusion (this page)</div>
 62→                </div>
 63→                <div className="rounded-lg border bg-card p-4">
 64→                    <div className="text-2xl font-bold text-red-600 tabular-nums">
 65→                        {exclusionCount}
 66→                    </div>
 67→                    <div className="text-xs text-muted-foreground">Exclusion (this page)</div>
 68→                </div>
 69→                <div className="rounded-lg border bg-card p-4">
 70→                    <div className="text-2xl font-bold text-blue-600 tabular-nums">
 71→                        {Math.round(avgConfidence * 100)}%
 72→                    </div>
 73→                    <div className="text-xs text-muted-foreground">Avg confidence</div>
 74→                </div>
 75→                <div className="rounded-lg border bg-card p-4">
 76→                    <div className="text-2xl font-bold text-purple-600 tabular-nums">
 77→                        {groundedCount}
 78→                    </div>
 79→                    <div className="text-xs text-muted-foreground">With grounding</div>
 80→                </div>
 81→            </div>
 82→
 83→            {/* Filters */}
 84→            <div className="rounded-lg border bg-card p-4">
 85→                <FilterBar
 86→                    criteriaType={criteriaType}
 87→                    setCriteriaType={(v) => {
 88→                        setCriteriaType(v);
 89→                        setPage(1);
 90→                    }}
 91→                    category={category}
 92→                    setCategory={(v) => {
 93→                        setCategory(v);
 94→                        setPage(1);
 95→                    }}
 96→                    minConfidence={minConfidence}
 97→                    setMinConfidence={(v) => {
 98→                        setMinConfidence(v);
 99→                        setPage(1);
100→                    }}
101→                />
102→            </div>
103→
104→            {/* Table */}
105→            {isLoading ? (
106→                <div className="flex items-center justify-center py-20">
107→                    <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
108→                    <span className="ml-3 text-muted-foreground">Loading criteria...</span>
109→                </div>
110→            ) : error ? (
111→                <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6 text-center">
112→                    <p className="text-destructive font-medium">Failed to load criteria</p>
113→                    <p className="text-sm text-muted-foreground mt-1">{String(error)}</p>
114→                </div>
115→            ) : (
116→                <CriteriaTable data={items} columns={columns} />
117→            )}
118→
119→            {/* Pagination */}
120→            {totalPages > 1 && (
121→                <div className="flex items-center justify-between">
122→                    <div className="text-sm text-muted-foreground">
123→                        Page {page} of {totalPages}
124→                    </div>
125→                    <div className="flex items-center gap-2">
126→                        <Button
127→                            variant="outline"
128→                            size="sm"
129→                            onClick={() => setPage((p) => Math.max(1, p - 1))}
130→                            disabled={page <= 1}
131→                        >
132→                            <ChevronLeft className="h-4 w-4 mr-1" />
133→                            Previous
134→                        </Button>
135→                        <Button
136→                            variant="outline"
137→                            size="sm"
138→                            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
139→                            disabled={page >= totalPages}
140→                        >
141→                            Next
142→                            <ChevronRight className="h-4 w-4 ml-1" />
143→                        </Button>
144→                    </div>
145→                </div>
146→            )}
147→        </div>
148→    );
149→}
