 92→function formatRelativeTime(dateStr: string): string {
 93→    const date = new Date(dateStr);
 94→    const now = new Date();
 95→    const diffMs = now.getTime() - date.getTime();
 96→    const diffSec = Math.floor(diffMs / 1000);
 97→    const diffMin = Math.floor(diffSec / 60);
 98→    const diffHr = Math.floor(diffMin / 60);
 99→    const diffDay = Math.floor(diffHr / 24);
100→
101→    if (diffSec < 60) return 'just now';
102→    if (diffMin < 60) return `${diffMin}m ago`;
103→    if (diffHr < 24) return `${diffHr}h ago`;
104→    if (diffDay < 30) return `${diffDay}d ago`;
105→    return date.toLocaleDateString();
106→}
