async () => {
  const token = localStorage.getItem('auth_token');
  const resp = await fetch('http://localhost:8000/criteria/structured?page=1&page_size=50&sort_by=confidence&sort_order=desc', {
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' }
  });
  const data = await resp.json();
  // Return just the COVID and Age criteria with their field_mappings
  const interesting = data.items.filter(i => 
    i.text.includes('COVID-19 starting') || i.text.includes('Age ≥ 18')
  ).map(i => ({
    text: i.text,
    entities: i.entities,
    field_mappings: i.field_mappings,
  }));
  return interesting;
}

async () => {
  const token = localStorage.getItem('auth_token');
  const resp = await fetch('http://localhost:8000/criteria/structured?page=1&page_size=50&sort_by=confidence&sort_order=desc', {
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' }
  });
  const data = await resp.json();
  const covid = data.items.find(i => i.text.includes('COVID-19 starting'));
  const age = data.items.find(i => i.text.includes('Age ≥ 18'));

  // For COVID, show field_mappings but truncate values
  const covidFm = (covid?.field_mappings || []).map(fm => ({
    entity: fm.entity,
    relation: fm.relation,
    value_type: fm.value?.type,
    value_val: typeof fm.value?.value === 'string' ? fm.value.value.slice(0, 100) + '...' : fm.value?.value,
    value_duration: typeof fm.value?.duration === 'string' ? fm.value.duration.slice(0, 100) + '...' : fm.value?.duration,
    value_unit: fm.value?.unit,
    value_min: fm.value?.min,
    value_max: fm.value?.max,
  }));

  return {
    covid: { text: covid?.text, entity_count: covid?.entities?.length, fm_count: covid?.field_mappings?.length, field_mappings: covidFm },
    age: { text: age?.text, entities: age?.entities, field_mappings: age?.field_mappings },
  };
}

